pub fn parse_quoted_list(s: &str) -> Option<Vec<String>> {
    if s.is_empty() {
        return Some(vec![]);
    }

    let mut result = Vec::new();
    let mut i = 0;
    let len = s.len();

    while i < len {
        let mut start = i;
        let mut in_quote = false;
        let mut chars = s.chars().peekable();

        while let Some(c) = chars.next() {
            if c == '"' {
                if in_quote {
                    if chars.peek() == Some(&'\"') {
                        chars.next(); // skip the second quote
                    } else {
                        break; // malformed: single closing quote
                    }
                } else {
                    in_quote = true;
                }
            } else if c == ',' && !in_quote {
                break; // unquoted comma
            }
            i += 1;
        }

        let field = &s[start..i];
        if !field.is_empty() {
            if !field.chars().all(|c| c == '"') {
                return None; // unquoted text
            }
            let field = field.trim();
            if field.is_empty() {
                result.push("");
            } else {
                result.push(field.replace('"', "\""));
            }
        }
    }

    Some(result)
}

